use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    // order: front = least recent, back = most recent
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let n: int = keys.len() as int
            let mut i = 0
            while i < n {
                if keys[i as usize] != k {
                    nk.push(keys[i as usize])
                    nv.push(vals[i as usize])
                }
                i += 1
            }
            nk.push(k)
            nv.push(v)
            if (nk.len() as int) > cap {
                println("evict ${nk[0]}")
                let mut ek: Vec<int> = []
                let mut ev: Vec<int> = []
                let mut j = 1
                while j < (nk.len() as int) {
                    ek.push(nk[j as usize])
                    ev.push(nv[j as usize])
                    j += 1
                }
                nk = ek
                nv = ev
            }
            keys = nk
            vals = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let n: int = keys.len() as int
            let mut i = 0
            while i < n {
                if keys[i as usize] != k {
                    nk.push(keys[i as usize])
                    nv.push(vals[i as usize])
                } else {
                    found = vals[i as usize]
                }
                i += 1
            }
            if (nk.len() as int) < n {
                nk.push(k)
                nv.push(found)
            }
            keys = nk
            vals = nv
            println("${found}")
        } else if cmd == "keys" {
            let n: int = keys.len() as int
            if n == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = n - 1
                while i >= 0 {
                    if i != n - 1 {
                        s = s + " "
                    }
                    s = s + "${keys[i as usize]}"
                    i -= 1
                }
                println("${s}")
            }
        }
    }
}

